<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $seed = json_decode(file_get_contents(__DIR__."/../scratch_seed.json"), true); foreach($seed["risks"] as $r) { if(empty($r["linkedActionIds"])) continue; $riesgo = Illuminate\Support\Facades\DB::table("riesgos")->where("local_id", $r["id"])->first(); if(!$riesgo) continue; foreach($r["linkedActionIds"] as $actIdStr) { $poaAct = null; foreach($seed["poaActions"] as $pa) { if($pa["id"] === $actIdStr) { $poaAct = $pa; break; } } if(!$poaAct) continue; $dbAct = Illuminate\Support\Facades\DB::table("acciones_sustantivas")->where("descripcion", "like", "%".trim($poaAct["text"])."%")->first(); if(!$dbAct) { $dbAct = Illuminate\Support\Facades\DB::table("actividades_sustantivas")->where("descripcion", "like", "%".trim($poaAct["text"])."%")->first(); } if($dbAct) { $actId = $dbAct->id ?? $dbAct->accion_sustantiva_id ?? null; if($actId) { Illuminate\Support\Facades\DB::table("actividad_riesgo")->updateOrInsert(["actividad_sustantiva_id" => $actId, "riesgo_id" => $riesgo->id]); echo "Linked ".$riesgo->local_id." to action: ".substr($poaAct["text"], 0, 30)."...\n"; } } } }
